"""HTML presentation generated by Python; no frontend framework or build step.

HTML/CSS are the browser's display formats. The only JavaScript below opens
Plaid's external login window; it does not classify or analyze transactions.
"""

from html import escape
from urllib.parse import urlencode


def text(value):
    return escape(str(value), quote=True)


def money(amount, currency, decimals=0):
    prefix = {"USD": "$", "CAD": "CA$", "EUR": "€", "GBP": "£"}.get(
        currency, currency + " "
    )
    return f"{prefix}{amount:,.{decimals}f}"


def chart(months, currency):
    """Draw a small accessible SVG bar chart directly from monthly totals."""
    maximum = max(1, *(max(month["income"], month["expenses"]) for month in months))
    ceiling = max(1000, int(maximum / 1000 + 1) * 1000)
    parts = [
        '<svg viewBox="0 0 900 270" role="img" aria-label="Monthly income and expenses"><title>Monthly income and expenses</title>'
    ]
    for step in range(5):
        value = ceiling * step / 4
        y = 220 - step * 48
        parts.append(
            f'<line x1="55" x2="890" y1="{y}" y2="{y}" stroke="#e5e7eb"/><text x="45" y="{y + 4}" text-anchor="end" fill="#718096" font-size="11">{value / 1000:g}k</text>'
        )
    for index, month in enumerate(months):
        x = 88 + index * 118
        for offset, key, color in [
            (0, "income", "#315d9c"),
            (30, "expenses", "#b8c0cc"),
        ]:
            height = max(0, month[key]) / ceiling * 192
            parts.append(
                f'<rect x="{x + offset}" y="{220 - height}" width="25" height="{height}" fill="{color}"><title>{text(month["month"])} {key}: {text(money(month[key], currency))}</title></rect>'
            )
        parts.append(
            f'<text x="{x + 28}" y="245" text-anchor="middle" fill="#687483" font-size="12">{text(month["label"])}</text>'
        )
    parts.append(
        '</svg><p class="legend"><span style="color:#315d9c">■ Income</span> &nbsp; <span style="color:#788390">■ Expenses</span></p>'
    )
    return "".join(parts)


def overview(report, currency):
    current = report["current"]
    metrics = [
        ("Income this month", money(current["income"], currency), "Month to date"),
        (
            "Monthly average",
            money(report["average"], currency),
            f"{report['complete_months']} completed months with records",
        ),
        (
            "Net cash flow",
            money(current["income"] - current["expenses"], currency),
            "Income − expenses this month",
        ),
        (
            "Income stability",
            "—" if report["score"] is None else f"{report['score']}/100",
            "Needs 3 completed months"
            if report["score"] is None
            else "Based on monthly income variation",
        ),
    ]
    totals = "".join(
        f"<div><dt>{text(label)}</dt><dd>{text(value)}</dd><small>{text(note)}</small></div>"
        for label, value, note in metrics
    )
    sources = "".join(
        f'<tr><td>{text(source["source"])}</td><td>{source["count"]}</td><td>{"Recurring · " + str(source["months"]) + " months" if source["recurring"] else "Occasional"}</td><td class="number">{text(money(source["total"], currency))}</td></tr>'
        for source in report["sources"]
    )
    if not sources:
        sources = '<tr><td colspan="4">No income found in this currency.</td></tr>'
    return f"""<dl class="totals">{totals}</dl>
    <section class="chart-section"><h3>Monthly income and expenses</h3><p class="muted">Six previous months and the current partial month.</p>{chart(report["months"], currency)}</section>
    <section><h3>Income sources</h3><p class="muted">Grouped by cleaned description over the displayed period.</p><div class="table-scroll"><table><thead><tr><th>Source</th><th>Payments</th><th>Pattern</th><th class="number">Total</th></tr></thead><tbody>{sources}</tbody></table></div></section>"""


RULES = """<section class="rules"><h3>How the data is processed</h3><ol>
<li><strong>Ingest:</strong> request records from Plaid Sandbox, or load the sample dataset.</li>
<li><strong>Clean:</strong> remove duplicate IDs and invalid records; normalize source names.</li>
<li><strong>Classify:</strong> posted credits count as income when the category or description supports it. Exclude transfers, refunds and pending payments; flag unknown credits.</li>
<li><strong>Summarize:</strong> group income by month, source and currency.</li></ol>
<p>Plaid uses negative amounts for incoming money. Below, each original description is paired with its cleaned result and the rule used.</p>
<details><summary>Stability and recurring income rules</summary><p>Stability = max(0, 100 × (1 − standard deviation ÷ average income)). We use completed months with records and require at least three. Months with activity but no income count as zero; missing history is excluded. This is descriptive, not a prediction.</p><p>A source is recurring when it appears in at least three distinct months. Grouping uses text rules and can make mistakes.</p></details></section><h3>Raw → cleaned records</h3>"""


def transaction_table(rows, view, mode, currency, query, kind):
    explain = view == "pipeline"
    filtered = [
        row
        for row in rows
        if (kind == "all" or row["kind"] == kind)
        and query.lower() in (row["name"] + " " + row["source"]).lower()
    ]
    options = "".join(
        f'<option value="{value}" {"selected" if kind == value else ""}>{value}</option>'
        for value in ["all", "income", "expense", "transfer", "review"]
    )
    hidden = "".join(
        f'<input type="hidden" name="{key}" value="{text(value)}">'
        for key, value in {"view": view, "mode": mode, "currency": currency}.items()
    )
    body = []
    for row in filtered:
        raw_or_source = (
            f"<code>{text(row['name'])}</code>" if explain else text(row["source"])
        )
        extra_source = f"<td>{text(row['source'])}</td>" if explain else ""
        extra_rule = f'<td class="rule">{text(row["reason"])}</td>' if explain else ""
        amount = money(
            abs(row["amount"]), row.get("iso_currency_code") or "Unknown currency"
        )
        pending = "<small>Pending</small>" if row.get("pending") else ""
        body.append(
            f'<tr><td class="date">{text(row["date"])}{pending}</td><td>{raw_or_source}</td>{extra_source}<td><span class="type {row["kind"]}">{row["kind"]}</span></td><td class="number">{"+" if row["amount"] < 0 else "−"}{text(amount)}</td>{extra_rule}</tr>'
        )
    table = (
        f'<div class="table-scroll"><table><thead><tr><th>Date</th><th>{"Original description" if explain else "Description"}</th>{"<th>Cleaned source</th>" if explain else ""}<th>Type</th><th class="number">Amount</th>{"<th>Rule</th>" if explain else ""}</tr></thead><tbody>{"".join(body)}</tbody></table></div>'
        if body
        else '<p class="empty">No matching transactions.</p>'
    )
    return f'''<form class="filters" method="get">{hidden}<input aria-label="Search transactions" name="q" placeholder="Search transactions" value="{text(query)}"><select aria-label="Classification" name="kind">{options}</select><button>Apply</button><span class="muted">{len(filtered)} records</span></form>{table}'''


def render_page(
    rows, report, currencies, currency, view, mode, connected, message, query, kind
):
    def url(**changes):
        return "/?" + urlencode(
            {"view": view, "mode": mode, "currency": currency, **changes}
        )

    labels = {
        "overview": "Overview",
        "transactions": "Transactions",
        "pipeline": "Data pipeline",
    }
    nav = "".join(
        f'<a href="{text(url(view=key))}" {"aria-current=page" if view == key else ""}>{label}</a>'
        for key, label in labels.items()
    )
    buttons = (
        f'<a class="button" href="{text(url(mode="sandbox"))}">Refresh</a><button id="disconnect">Disconnect</button>'
        if connected
        else '<button id="connect" class="primary">Connect Sandbox</button>'
    )
    note = (
        "<strong>Plaid Sandbox</strong> · Simulated bank records. No real bank connected."
        if mode == "sandbox"
        else "<strong>Sample data</strong> · Generated locally. Connect Plaid Sandbox to use test-bank records."
    )
    if connected and mode == "sandbox":
        note += f'<a href="{text(url(mode="demo"))}">Show sample data</a>'
    options = "".join(
        f"<option {'selected' if value == currency else ''}>{text(value)}</option>"
        for value in currencies
    )
    currency_form = f'<form method="get"><input type="hidden" name="view" value="{view}"><input type="hidden" name="mode" value="{mode}"><label>Currency <select name="currency" aria-label="Currency">{options}</select></label><button>Update</button></form>'
    content = (
        overview(report, currency)
        if view == "overview"
        else (RULES if view == "pipeline" else "")
        + transaction_table(rows, view, mode, currency, query, kind)
    )
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IncomeLens</title><style>{STYLE}</style></head><body><main class="container">
    <header><div><h1>IncomeLens</h1><p>Income and cash flow from bank transactions.</p></div><div class="actions">{buttons}</div></header>
    <div class="data-note">{note}</div><p id="message" role="status" class="message" {"" if message else "hidden"}>{text(message)}</p>
    <nav aria-label="Views">{nav}</nav><div class="section-heading"><h2>{labels[view]}</h2><div class="actions">{currency_form}<a class="button" href="/export?mode={mode}">Export JSON</a></div></div>
    {content}<footer><span>Sandbox project · {len(rows)} records · {report["review"]} flagged for review</span><span>Python · totals are separate by currency.</span></footer></main>
    <script src="https://cdn.plaid.com/link/v2/stable/link-initialize.js"></script><script>{PLAID_LOGIN}</script></body></html>"""


# Browser display rules, kept here so there is no separate frontend project.
STYLE = """
*{box-sizing:border-box}body{margin:0;background:#fff;color:#20252d;font:14px Arial,Helvetica,sans-serif}.container{max-width:1120px;margin:auto;padding:38px 30px}header,.actions,.section-heading,.data-note,footer{display:flex;align-items:center;justify-content:space-between;gap:12px}header{margin-bottom:25px}h1{font-size:25px;margin:0 0 8px}h2{font-size:19px;margin:0}h3{font-size:15px;margin:0 0 9px}header p,.muted{color:#6d7580;font-size:13px}header p{margin:0}button,.button,input,select{font:inherit;border:1px solid #cfd4dc;border-radius:4px;padding:8px 12px;background:white;color:#303844}button,.button,select{cursor:pointer}.button{text-decoration:none;display:inline-block}button:hover,.button:hover{background:#f4f6f8}.primary{color:white;background:#315d9c;border-color:#315d9c}button:disabled{opacity:.5;cursor:wait}a{color:#315d9c}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid #315d9c;outline-offset:3px}.data-note{background:#f5f7fa;border:1px solid #e0e4e9;padding:13px;font-size:12px;color:#626c7a;border-radius:4px;justify-content:flex-start;flex-wrap:wrap}.message{padding:13px;background:#fff9e9;border:1px solid #e8dbb5;font-size:13px}nav{display:flex;gap:25px;border-bottom:1px solid #dce1e7;margin:25px 0}nav a{text-decoration:none;padding:12px 0;border-bottom:2px solid transparent;color:#727b87;font-size:13px}nav a[aria-current]{color:#264f89;border-color:#315d9c;font-weight:bold}.section-heading{margin-bottom:24px}.section-heading .actions{font-size:12px}.section-heading form{display:flex;gap:8px;align-items:center}.totals{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;padding-bottom:25px;border-bottom:1px solid #e1e5eb;margin:0 0 28px}.totals dt{color:#647080;font-size:12px;margin-bottom:12px}.totals dd{font-size:28px;margin:0 0 7px;font-variant-numeric:tabular-nums}.totals small{font-size:11px;color:#848c97;line-height:1.6}section{margin-bottom:32px}.chart-section{border-bottom:1px solid #e1e5eb;padding-bottom:20px}svg{width:100%;display:block;min-height:190px}.legend{text-align:center;font-size:12px}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}th{font-weight:normal;font-size:11px;color:#748092;background:#f8f9fb;border-bottom:1px solid #d5dce5;padding:12px 10px}td{padding:13px 10px;border-bottom:1px solid #eceff3;vertical-align:top}.number{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.date{white-space:nowrap;color:#77808c;font-size:12px}.type{font-size:11px;color:#76808e}.income{color:#326d4c}.review{color:#927123}.filters{display:flex;gap:10px;align-items:center;margin:20px 0}.filters input:not([type=hidden]){width:230px}.filters .muted{margin-left:auto}.rules{font-size:13px;line-height:1.8;border-bottom:1px solid #e1e5eb;padding-bottom:24px}.rules li{margin-bottom:8px}.rules p{color:#687483}summary{cursor:pointer;color:#315d9c}.rule{min-width:230px;max-width:300px;font-size:12px;color:#687483;line-height:1.6}code{font-size:11px;overflow-wrap:anywhere}small{display:block;font-size:10px;color:#818a98;margin-top:4px}footer{border-top:1px solid #e1e5eb;margin-top:35px;padding-top:18px;font-size:11px;color:#88919d}.empty{padding:24px 0;color:#818a96}
@media(max-width:700px){.container{padding:24px 18px}header,.section-heading{align-items:flex-start;flex-direction:column}.totals{grid-template-columns:repeat(2,1fr);gap:25px 16px}.totals dd{font-size:26px}.actions{flex-wrap:wrap;justify-content:flex-start}.filters{flex-wrap:wrap}.filters input:not([type=hidden]){width:180px}.filters .muted{margin-left:0}table{min-width:540px}footer{align-items:flex-start;flex-direction:column}}
"""

# The entire browser-side program: Plaid's SDK needs a JavaScript callback.
PLAID_LOGIN = """
const message = document.getElementById('message');
function showError(error) { message.hidden = false; message.textContent = error.message; }
async function request(action, values = {}) {
  const response = await fetch('/api/plaid', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({action, ...values})});
  const data = await response.json();
  if (!response.ok) throw new Error(data.error);
  return data;
}
const connect = document.getElementById('connect');
if (connect) connect.onclick = async () => {
  connect.disabled = true;
  try {
    if (!window.Plaid) throw new Error('Plaid could not load. Please retry.');
    const data = await request('link');
    const handler = Plaid.create({token:data.link_token,
      onSuccess: async (public_token) => {
        try { await request('exchange', {public_token}); window.location.href = '/?mode=sandbox'; }
        catch (error) { showError(error); connect.disabled = false; }
      },
      onExit: (error) => { handler.destroy(); connect.disabled = false; if (error) showError(new Error('Plaid connection closed. Please retry.')); }
    });
    handler.open();
  } catch (error) { showError(error); connect.disabled = false; }
};
const disconnect = document.getElementById('disconnect');
if (disconnect) disconnect.onclick = async () => {
  disconnect.disabled = true;
  try { await request('disconnect'); window.location.href = '/'; }
  catch (error) { showError(error); disconnect.disabled = false; }
};
"""
